// index.js - minimal Lambda handler (Node)
const fetch = require('node-fetch');
const LRU = require('lru-cache');
const cache = new LRU({ max: 500, ttl: Number(process.env.CACHE_TTL || 30000) });

exports.handler = async (event) => {
  const body = JSON.parse(event.body || '{}');
  const prompt = body.prompt || 'Hello';

  // simple cache key by prompt prefix
  const key = prompt.slice(0, 200);
  if (cache.has(key)) {
    return { statusCode: 200, body: JSON.stringify({ source: 'cache', text: cache.get(key) }) };
  }

  const res = await fetch('https://api.redwood.ai/v1/generate', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${process.env.REDWOOD_API_KEY}`,
      'Content-Type': 'application/json',
      'x-redwood-request-id': `srv-${Date.now()}`
    },
    body: JSON.stringify({ model: process.env.REDWOOD_MODEL || 'gpt-small-compat', prompt })
  });

  if (!res.ok) {
    // simple fallback: return canned response for demo
    const fallback = 'Service temporarily unavailable, please try again';
    return { statusCode: res.status, body: JSON.stringify({ source: 'fallback', text: fallback }) };
  }

  const payload = await res.json();
  const text = payload.text || payload.choices?.[0]?.text || '';
  cache.set(key, text);
  return { statusCode: 200, body: JSON.stringify({ source: 'redwood', text }) };
};

